{
  "name": "PICA 启动器应用",
  "name_en": "PICA Launcher App",
  "manufacturer": "",
  "description": "用于实验软件资源访问与脚本启动的非实体桌面应用。它提供图形界面来创建启动器与资源面板、打开说明文档和仓库链接、定位脚本目录、启动相关脚本、输出日志，并可运行 GPIB 测试工具，适合在实验环境中集中入口管理各类实用程序。",
  "description_en": "A non-physical desktop application for accessing experiment-related resources and launching scripts. It provides a GUI to build launcher and resource panels, open documentation and repository links, locate script folders, run related scripts, display logs, and start a GPIB test utility, serving as a central entry point for lab utilities.",
  "actions": [
    {
      "action_name": "auto-create_launcher_panel",
      "description": "创建启动器面板，用于在界面中组织和显示可启动的实验脚本与工具入口。",
      "description_en": "Create the launcher panel to organize and display launchable experiment scripts and utility entry points in the GUI."
    },
    {
      "action_name": "auto-create_resource_panel",
      "description": "创建资源面板，用于显示文档、版本、许可证和仓库等资源入口。",
      "description_en": "Create the resource panel to present links to documentation, version information, license, and repository resources."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建应用界面组件，初始化启动器与资源相关的图形控件。",
      "description_en": "Create the application widgets and initialize GUI components related to the launcher and resources."
    },
    {
      "action_name": "auto-launch_script",
      "description": "启动指定脚本，作为实验相关实用程序或子应用的入口。",
      "description_en": "Launch a specified script as an entry point to an experiment-related utility or sub-application."
    },
    {
      "action_name": "auto-log",
      "description": "记录日志消息，并在界面控制台中附带时间戳显示。",
      "description_en": "Log a message and display it with a timestamp in the application's console widget."
    },
    {
      "action_name": "auto-open_license",
      "description": "打开许可证信息，便于查看软件授权内容。",
      "description_en": "Open the license information so the software licensing terms can be viewed."
    },
    {
      "action_name": "auto-open_manual_file",
      "description": "打开手册文件，便于查看软件使用说明。",
      "description_en": "Open the manual file so the software usage instructions can be viewed."
    },
    {
      "action_name": "auto-open_readme",
      "description": "打开 README 文档，便于查看项目简介与使用说明。",
      "description_en": "Open the README document to view the project overview and usage notes."
    },
    {
      "action_name": "auto-open_repo",
      "description": "打开项目仓库链接，便于访问源代码或在线资源页面。",
      "description_en": "Open the project repository link to access source code or related online resources."
    },
    {
      "action_name": "auto-open_script_folder",
      "description": "打开指定脚本所在文件夹，便于查看、管理或手动运行相关文件。",
      "description_en": "Open the folder containing a specified script for inspection, management, or manual execution."
    },
    {
      "action_name": "auto-open_updates",
      "description": "打开更新信息入口，便于查看软件版本更新内容。",
      "description_en": "Open the updates entry to view software version changes and update information."
    },
    {
      "action_name": "auto-run_gpib_test",
      "description": "运行 GPIB 测试工具，用于检查实验通信环境中的 GPIB 相关功能。",
      "description_en": "Run the GPIB test utility to check GPIB-related functionality in the lab communication environment."
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置界面样式，定义应用图形界面的显示风格。",
      "description_en": "Set up the GUI styles to define the application's visual appearance."
    }
  ],
  "tag_hints": [
    "GUI launcher",
    "script launching",
    "lab utility app",
    "resource/document access",
    "desktop application",
    "GPIB test utility",
    "experiment software hub"
  ]
}

